  source
    .split(NODE_MANIFEST_LOADER_PATH_NEEDLE)
    .join(NODE_MANIFEST_LOADER_PATH_REPLACEMENT)
    .split(NODE_MANIFEST_LOADER_REQUIRE_NEEDLE)
